import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;
import org.apache.abdera.parser.ParserOptionsImpl;

/**
 * A thread‑safe provider for reading and writing Atom {@link Element}s.
 *
 * <p>The original implementation suffered from an XXE vulnerability because
 * the {@link Parser} was reused across threads and the {@code resolveEntities}
 * option was set inside a synchronized block that did not guarantee that the
 * option was applied before parsing.  The patched version creates a fresh
 * {@link ParserOptions} instance for each request, sets {@code
 * resolveEntities} to {@code false} (disabling external entity resolution),
 * and passes those options directly to {@link Parser#parse(InputStream,
 * ParserOptions)}.  This eliminates the race condition and ensures that
 * entity expansion is never performed.</p>
 */
public abstract class AbstractAtomProvider<T extends Element> implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods omitted for brevity

    @Override
    public T readFrom(Class<T> clazz, Type t, Annotation[] a, MediaType mt,
                      MultivaluedMap<String, String> headers, InputStream is) throws IOException {
        // Obtain a parser instance from the shared engine
        Parser parser = ATOM_ENGINE.getParser();

        // Create a brand‑new ParserOptions object for this invocation
        ParserOptions options = new ParserOptionsImpl();
        options.setResolveEntities(false);          // Disable external entity resolution
        options.setAutodetectCharset(autodetectCharset); // Preserve existing charset handling

        // Parse the input stream with the secure options
        Document<T> doc = parser.parse(is, options);
        return doc.getRoot();
    }

    // other methods omitted for brevity
}
```

