     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  if {@code name} resolves outside {@code dir},
     *                                  or if {@code dir} is not a directory
     */
    public static File allocateFile(File dir, String name) {
        // Basic null checks
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Reject empty names – they would result in an invalid file
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be empty");
        }

        // Strip query parameters (e.g. "?foo=bar") if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the name against the base directory and normalize the path
        Path dirPath = dir.toPath().normalize();
        Path namePath = Paths.get(name).normalize();

        // Reject absolute paths – they would ignore the base directory
        if (namePath.isAbsolute()) {
            throw new IllegalArgumentException("Absolute file names are not allowed");
        }

        // Resolve and normalize the full target path
        Path targetPath = dirPath.resolve(namePath).normalize();

        // Ensure the target remains inside the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "File name escapes the target directory: " + name);
        }

        // Convert back to File for compatibility with existing logic
        File file = targetPath.toFile();

        // Prepare prefix/suffix for generating unique names
        String baseName = namePath.getFileName().toString();
        int dot = baseName.indexOf('.');
        String prefix = (dot < 0) ? baseName : baseName.substring(0, dot);
        String suffix = (dot < 0) ? "" : baseName.substring(dot);

        // Append numeric suffixes until we find a non‑existing file
        int index = 2;
