    /**
     * Extracts a single entry from the archive into {@code dir}.  The method now
     * performs strict validation of {@code entryName} to prevent Zip‑Slip attacks.
     *
     * @param srcF              the source file in the archive (unused in this implementation)
     * @param dir               the target extraction directory
     * @param compressedInputStream the input stream containing the compressed data for this entry
     * @param entryName         the name of the entry as stored in the archive
     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the Unix permission bits for the entry (may be {@code null})
     * @param symlinkDestination the target of a symbolic link (may be {@code null})
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry is unsafe or cannot be extracted
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        if (entryName == null) {
            throw new IllegalArgumentException("entryName must not be null");
        }

        // Resolve the target file relative to the extraction directory
        final File f = FileUtils.resolveFile(dir, entryName);

        // Canonicalise both the target directory and the resolved file to detect
        // directory traversal attempts (Zip‑Slip).
        final Path canonicalDirPath = dir.getCanonicalFile().toPath();
        final Path canonicalDestPath = f.getCanonicalFile().toPath();

        if (!canonicalDestPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException("Entry '" + entryName + "' is outside of the target directory");
        }

        // Prevent a regular file from overriding an existing symbolic link
        if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalDestPath)) {
            throw new ArchiverException("Attempt to overwrite existing symbolic link with entry '" + entryName + "'");
        }

        try {
            // Skip extraction if the file already exists and is up‑to‑date
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Ensure parent directories exist
            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                // Create a symbolic link pointing to the specified destination
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                // Create the directory
                f.mkdirs();
            } else {
                // Write the file contents
                try (OutputStream out = new FileOutputStream(f)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Preserve the original modification time
            f.setLastModified(entryDate.getTime());

            // Apply Unix permissions if requested
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
