import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely extracts archive entries into {@code targetDirectory}.  The method
     * performs rigorous path validation to prevent path‑traversal attacks.
     *
     * @param supplier      supplies archive entries
     * @param writer        writes entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which entries are extracted
     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        Path targetDirPath = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name.
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has an invalid name");
            }
            // Reject absolute paths, drive letters, and any component that is "..".
            if (entryName.contains("..") ||
                entryName.startsWith("/") ||
                entryName.startsWith("\\") ||
                entryName.matches("^[A-Za-z]:.*")) {
                throw new IOException("archive entry name is unsafe: " + entryName);
            }

            // Resolve the entry path against the target directory and normalize.
            Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of "
                                + targetDirectory);
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the entry data.
                try (OutputStream out = Files.newOutputStream(
                        entryPath, StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
