import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

/**
 * A thread‑safe XPath builder that safely parses XML documents.
 *
 * <p>The {@link #doGetDocument} method has been updated to protect against XML External Entity
 * (XXE) attacks by configuring a {@link DocumentBuilderFactory} with secure settings and
 * parsing XML input directly. This eliminates the risk of external entity resolution
 * when converting strings or streams to {@link Document} objects.</p>
 */
public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing helpers
    // -------------------------------------------------------------------------

    /**
     * Creates a {@link DocumentBuilderFactory} configured to mitigate XXE attacks.
     *
     * @return a secure {@link DocumentBuilderFactory}
     * @throws Exception if the factory cannot be configured
     */
    private static DocumentBuilderFactory newSecureDocumentBuilderFactory() throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // Enable secure processing
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disallow DOCTYPE declarations
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external entity resolution
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        return dbf;
    }

    /**
     * Parses the given source into a {@link Document} using a secure {@link DocumentBuilder}.
     *
     * @param source the XML source, either a {@link String} or an {@link InputStream}
     * @return the parsed {@link Document}
     * @throws Exception if parsing fails
     */
    private static Document parseSecureDocument(Object source) throws Exception {
        DocumentBuilderFactory dbf = newSecureDocumentBuilderFactory();
        DocumentBuilder db = dbf.newDocumentBuilder();

        if (source instanceof String) {
            return db.parse(new InputSource(new StringReader((String) source)));
        } else if (source instanceof InputStream) {
            return db.parse((InputStream) source);
        } else {
            throw new IllegalArgumentException(
                "Unsupported source type for secure XML parsing: " + source.getClass());
        }
    }

    // -------------------------------------------------------------------------
    // Core logic
    // -------------------------------------------------------------------------

    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;

        // Attempt normal type conversion first
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter()
                                 .convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e;
            }
        }

        // If conversion failed or returned null, handle known body types securely
        if (answer == null) {
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext()
                                         .getTypeConverter()
                                         .convertTo(InputStream.class, exchange, body);
                answer = parseSecureDocument(is);
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext()
                                            .getTypeConverter()
                                            .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                answer = parseSecureDocument(body);
            }
        }

        // Fallback handling
        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods omitted for brevity
}
