import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.Objects;

/**
 * Utility class that determines whether a SCIM user self‑update request is allowed.
 *
 * <p>In a production environment the request must be performed by the user who owns the
 * account being updated.  The original implementation only compared the values in the
 * request payload against the stored user record, which allowed an attacker to change
 * another user’s email address.  The patched implementation now verifies that the
 * authenticated principal matches the target user ID extracted from the request URL.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the incoming HTTP request is permitted to perform a self‑update
     * on the specified SCIM user.
     *
     * @param request the HTTP request containing the SCIM user payload
     * @return {@code true} if the request is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // Read the request body once and parse it into a ScimUser instance
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // Extract the target user ID from the request URL
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );

        // Retrieve the current user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed (e.g., creation)
            return true;
        }

        /* -------------------------------------------------------------------------
         * Authorization check – ensure the authenticated user is the same as the
         * target user.  This prevents an attacker from modifying another user’s
         * account data.
         * ------------------------------------------------------------------------- */
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication == null || !authentication.isAuthenticated()) {
            return false; // No authenticated principal – deny access
        }

        Object principal = authentication.getPrincipal();
        String authenticatedUserId = null;

        // The principal may be a custom UAA token or a simple username string.
        // Attempt to extract the user ID in a defensive manner.
        if (principal instanceof org.cloudfoundry.identity.uaa.oauth.token.UaaToken) {
            authenticatedUserId = ((org.cloudfoundry.identity.uaa.oauth.token.UaaToken) principal).getUserId();
        } else if (principal instanceof org.springframework.security.core.userdetails.UserDetails) {
            authenticatedUserId = ((org.springframework.security.core.userdetails.UserDetails) principal).getUsername();
        } else if (principal instanceof String) {
            authenticatedUserId = (String) principal;
        }

        if (!Objects.equals(authenticatedUserId, id)) {
            return false; // The request is not performed by the account owner
        }

        /* -------------------------------------------------------------------------
         * Field validation – compare the incoming payload against the stored record.
         * Use Objects.equals to safely handle null values.
         * ------------------------------------------------------------------------- */
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the request is allowed
        return true;
    }

    // other methods
}
